selector_to_html = {"a[href=\"#multi-backend-hardware-support\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-backend hardware support<a class=\"headerlink\" href=\"#multi-backend-hardware-support\" title=\"Link to this heading\">#</a></h3><p>FlagGems supports a wide range of hardware platforms (10+ backends) and\nhas been extensively tested across different hardware configurations.\nFor a comprehensive and up to date list of supported platforms,\nplease check <a class=\"reference internal\" href=\"platforms.html\"><span class=\"doc std std-doc\">platforms supported</span></a>.</p>", "a[href=\"../references/operators.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator List<a class=\"headerlink\" href=\"#operator-list\" title=\"Link to this heading\">#</a></h1>", "a[href=\"#c-wrapped-operators\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">C+\u00b1wrapped operators<a class=\"headerlink\" href=\"#c-wrapped-operators\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#eager-mode-ready-independent-of-torch-compile\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Eager-mode ready, independent of <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code><a class=\"headerlink\" href=\"#eager-mode-ready-independent-of-torch-compile\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#hand-optimized-performance-for-selected-operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hand-optimized Performance for Selected Operators<a class=\"headerlink\" href=\"#hand-optimized-performance-for-selected-operators\" title=\"Link to this heading\">#</a></h2><p>The following chart shows the speedup of FlagGems compared with PyTorch ATen library in eager mode.\nThe speedup is calculated by averaging the speedup on each shape, representing the overall performance of the operator.</p><p><a data-lightbox=\"image-set\" href=\"../_images/speedup-20251225.png\">\n<img alt=\"Operator Speedup\" src=\"../_images/speedup-20251225.png\"/></a>\n</p>", "a[href=\"platforms.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Platforms Supported<a class=\"headerlink\" href=\"#platforms-supported\" title=\"Link to this heading\">#</a></h1><p><em>FlagGems</em> supports 10+ backends. The currently supported platforms and\ntheir capabilities are listed blow:</p>", "a[href=\"pointwise-dynamic.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Pointwise Dynamic Operators<a class=\"headerlink\" href=\"#pointwise-dynamic-operators\" title=\"Link to this heading\">#</a></h1><h2>1. Pointwise operations<a class=\"headerlink\" href=\"#pointwise-operations\" title=\"Link to this heading\">#</a></h2><p>Pointwise operators are trivial to parallelize.\nMost parallel programming guides begin with pointwise addition\nbetween 2 contiguous vectors.\nFor <a class=\"reference external\" href=\"https://triton-lang.org/main/getting-started/tutorials/01-vector-add.html#sphx-glr-getting-started-tutorials-01-vector-add-py\"><code class=\"docutils literal notranslate\"><span class=\"pre\">vector_add</span></code> in Triton</a>,\nit is simple to implement a task partitioning schema that each CTA reads a contiguous range\nfrom each input vector and writes to a contiguous range of the output vector.</p><p>However, actual use caes for pointwise operators may be more complicated.</p>", "a[href=\"#rich-collection-of-operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Rich Collection of Operators<a class=\"headerlink\" href=\"#rich-collection-of-operators\" title=\"Link to this heading\">#</a></h2><p>FlagGems features a large collection of PyTorch compatible operators.\nRefer to <a class=\"reference internal\" href=\"../references/operators.html\"><span class=\"doc std std-doc\">operator supported</span></a> and\n<a class=\"reference internal\" href=\"../references/experimental.html\"><span class=\"doc std std-doc\">experimental operators</span></a>\nfor list of formally supported operators and experimental operators.</p>", "a[href=\"#c-triton-function-dispatcher\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">C++ Triton Function Dispatcher<a class=\"headerlink\" href=\"#c-triton-function-dispatcher\" title=\"Link to this heading\">#</a></h3><p><em>FlagGems</em> can be installed either as a pure Python package or as a package with C++ extensions.\nThe C++ runtime is designed to address the overhead of the Python runtime\nand improve end-to-end performance.</p><p>There is an ongoing work that implements the Triton function dispatcher\nin C++ language. Stay tuned.</p>", "a[href=\"#features-overview\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Features Overview<a class=\"headerlink\" href=\"#features-overview\" title=\"Link to this heading\">#</a></h1><h2>Rich Collection of Operators<a class=\"headerlink\" href=\"#rich-collection-of-operators\" title=\"Link to this heading\">#</a></h2><p>FlagGems features a large collection of PyTorch compatible operators.\nRefer to <a class=\"reference internal\" href=\"../references/operators.html\"><span class=\"doc std std-doc\">operator supported</span></a> and\n<a class=\"reference internal\" href=\"../references/experimental.html\"><span class=\"doc std std-doc\">experimental operators</span></a>\nfor list of formally supported operators and experimental operators.</p>", "a[href=\"#function-level-kernel-dispatching\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Function-level kernel dispatching<a class=\"headerlink\" href=\"#function-level-kernel-dispatching\" title=\"Link to this heading\">#</a></h2><p>FlagGems introduces <code class=\"docutils literal notranslate\"><span class=\"pre\">LibEntry</span></code>, which independently manages the kernel cache and\nbypasses the runtime of <code class=\"docutils literal notranslate\"><span class=\"pre\">Autotuner</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">Heuristics</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">JitFunction</span></code>.\nTo use this feature, simply decorate the Triton kernel with <code class=\"docutils literal notranslate\"><span class=\"pre\">LibEntry</span></code>.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">LibEntry</span></code> also supports direct wrapping of <code class=\"docutils literal notranslate\"><span class=\"pre\">Autotuner</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">Heuristics</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">JitFunction</span></code>,\npreserving full tuning functionality. However, it avoids nested runtime type invocations,\neliminating redundant parameter processing. This means no need for binding or type wrapping,\nresulting in a simplified cache key format and reduced unnecessary key computation.</p>", "a[href=\"#automatic-code-generation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Automatic Code Generation<a class=\"headerlink\" href=\"#automatic-code-generation\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> provides an automatic code generation mechanism that enables developers\nto easily generate both pointwise and fused operators.\nThe auto-generation system supports a variety of requirements, including standard\nelement-wise computations, non-tensor parameters, and specifying output data types.\nFor more details, please refer to the <a class=\"reference internal\" href=\"pointwise-dynamic.html\"><span class=\"doc std std-doc\">pointwise dynamic</span></a>\ndocumentation.</p>", "a[href=\"../references/experimental.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagGems Experimental Operators<a class=\"headerlink\" href=\"#flaggems-experimental-operators\" title=\"Link to this heading\">#</a></h1><p>This document lists all experimental operators in FlagGems that have achieved an average speedup of 0.8x or higher compared to PyTorch implementations.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
